def get_good_numbers_v2(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    good_numbers = set()
    # m = p1^(2k1) * p2^(2k2) * ... * pr^(2kr)
    # r >= 2, kj >= 1

    # We can use a recursive function to generate these numbers
    def generate(prime_idx, current_m, num_primes):
        if num_primes >= 2:
            good_numbers.add(current_m)

        for i in range(prime_idx, len(primes)):
            p = primes[i]
            # k can be 1, 2, 3, ...
            k = 1
            while True:
                m_next = current_m * (p**(2*k))
                if m_next > limit:
                    break
                generate(i + 1, m_next, num_primes + 1)
                k += 1

    generate(0, 1, 0)
    return sorted(list(good_numbers))

